cat > sim3.py <<'EOF'
import numpy as np, json, math, sys
from joint import *
ml,data=load()
mu,sig,q=joint_fit(ml,data)
cells=sorted(ml)
def golden(f,lo,hi,it=60):
    for _ in range(it):
        a=lo+(hi-lo)*0.382; b=lo+(hi-lo)*0.618
        if f(a)<f(b): hi=b
        else: lo=a
    return 0.5*(lo+hi)
def cell_fit(x,qb):
    # per-cell joint fit with own sigma, q known
    n=len(x); S=x.sum(); SS=(x*x).sum()
    def nll(m,s):
        P=Phi((C-m)/s)
        return n*math.log(s)+(SS-2*m*S+n*m*m)/(2*s*s)-(N-n)*math.log(max(1-qb*P,1e-300))
    m=x.mean(); s=x.std()
    for it in range(20):
        m=golden(lambda v:nll(v,s),m-0.3,m+0.3); s=golden(lambda v:nll(m,v),0.03,0.2)
    return m,s
rng=np.random.default_rng(int(sys.argv[1])); R=int(sys.argv[2])
Q={'q04':((0.001,512,'wsd',0.5,'bf16'),(0.001,512,'wsd',1.0,'bf16')),
   'q10':((0.001,512,'wsd',1.0,'bf16'),(0.001,1024,'wsd',1.0,'bf16'))}
Rc={'r2':(0.001,512,'cosine',0.5,'bf16'),'r3':(0.001,512,'wsd',1.0,'bf16')}
errs={}
def add(k,v): errs.setdefault(k,[]).append(v)
need=set(sum([list(v) for v in Q.values()],[]))|set(Rc.values())
for r in range(R):
    sd={}; truthG={}
    for k in cells:
        x=rng.normal(mu[k],sig,N)
        pre=rng.random(N)>q[k[1]]; g=x>C
        sd[k]=x[(~pre)&(~g)]
        truthG[k]=((g&~pre).sum()/N, g.sum()/N)
    # q estimate: pooled from cells with negligible guard (lr<=0.0003) : q = mean n/N  (approx)
    q2={b:np.mean([len(sd[k])/N for k in cells if k[1]==b and k[0]<=0.0003]) for b in (256,512,1024)}
    fits={k:cell_fit(sd[k],q2[k[1]]) for k in need}
    for qid,(a,b) in Q.items(): add(qid,(fits[b][0]-fits[a][0])-(mu[b]-mu[a]))
    for rid,k in Rc.items():
        m,s=fits[k]; Pg=1-Phi((C-m)/s)
        add(rid+'_F1_vsGF',Pg-truthG[k][1]); add(rid+'_F2_vsPF',q2[k[1]]*Pg-truthG[k][0])
json.dump(errs,open('sim3_%s.json'%sys.argv[1],'w'))
EOF
